parameters.new_string:
async _loadMusic() {
  // Album JSON locations (where album.json lives).
  // Shared paths first: the deploy layout keeps album metadata + MP3s in
  // deploy/shared/audio/. The inthebeginning-bounce folder itself has no
  // audio/ subdirectory, so probing `audio/album.json` first produced a
  // spurious 404 before the user had even picked a sound mode.
  const albumJsonPaths = [
    '../../shared/audio/tracks/album.json',
    '../../shared/audio/metadata/v1/album.json',
    '../shared/audio/tracks/album.json',
    'audio/album.json',
  ];
  // Audio base URLs (where the MP3 files live) — same ordering rationale.
  const audioBases = [
    '../../shared/audio/tracks/',
    '../shared/audio/tracks/',
    'audio/',
  ];

  // Load album.json from the first available location
  let albumData = null;
  for (const path of albumJsonPaths) {
    try {
      const resp = await fetch(path);
      if (resp.ok) {
        albumData = await resp.json();
        break;
      }
    } catch (e) {
      console.debug(`_loadMusic: album.json not at ${path} (${e.message})`);
    }
  }

  if (!albumData) return;

  // Pick the first audioBase whose directory responds OK to a HEAD on the
  // first track. Shared-first ordering means this usually succeeds on the
  // first try with no 404 noise.
  const firstTrack = (albumData.tracks || [])[0];
  const mp3File = firstTrack?.audio_file || firstTrack?.file;
  let audioBase = audioBases[0];

  if (mp3File) {
    for (const base of audioBases) {
      try {
        const resp = await fetch(base + mp3File, { method: 'HEAD' });
        if (resp.ok) {
          audioBase = base;
          break;
        }
      } catch (e) {
        console.debug(`_loadMusic: audio base ${base} probe failed (${e.message})`);
      }
    }
  }

