parameters.new_string:
const sf2Paths = [
  '../../shared/audio/soundfonts/FluidR3_GM.sf2',
  '../shared/audio/soundfonts/FluidR3_GM.sf2',
  'audio/soundfonts/FluidR3_GM.sf2',
];

// Walk the candidate paths. HEAD is used to probe reachability; the
// real validation (RIFF magic bytes, size sanity, LFS pointer
// detection) happens inside SpessaBridge.init, which throws a
// descriptive Error on failure. Collect errors so we can report them.
let sf2Loaded = false;
const sf2Errors = [];
for (const sf2Path of sf2Paths) {
  try {
    const testResp = await fetch(sf2Path, { method: 'HEAD' });
    if (!testResp.ok) {
      sf2Errors.push(`${sf2Path}: HTTP ${testResp.status}`);
      continue;
    }
    sf2Loaded = await this.player._spessaBridge.init(sf2Path);
    if (sf2Loaded) break;
  } catch (e) {
    // Surface the actual SpessaBridge error so the user can act on it.
    console.error(`HiFi: ${sf2Path} failed to load:`, e);
    sf2Errors.push(`${sf2Path}: ${e.message}`);
  }
}

if (!sf2Loaded) {
  const summary = sf2Errors.join(' | ') || 'no candidate paths reachable';
  console.error(
    `HiFi: SoundFont could not be loaded from any candidate path.\n` +
    `  Errors: ${summary}\n` +
    `  Falling back to Synth mode.`
  );
  // Visible banner: prefix with ⚠ so the user notices the fallback.
  // This intentionally stays in the HUD until the first real track
  // name update, so it cannot be missed.
  if (this.hudTrack) {
    this.hudTrack.textContent = '⚠ HiFi unavailable — playing Synth (see console)';
    this.hudTrack.style.color = '#ff6060';
    // Clear the red warning after 8 seconds — the Synth mode will
    // overwrite the text on the next track change anyway, but this
    // ensures the warning is visible for at least that long.
    setTimeout(() => {
      if (this.hudTrack) this.hudTrack.style.color = '';
    }, 8000);
  }
  // Fall back to regular synth
  this.player.setMode(AUDIO_MODE.SYNTH);
  this.player.musicGenerator.seed = Date.now();
  this.player.musicGenerator.generate();
  this.player.musicGenerator._synth = this.player._synth;
  await this.player.play();
  break;
}

