async initSamples(baseUrl) {
  if (!this.ctx) this.init();
  this.sampleBank = new SampleBank();

  // Try multiple paths to find samples. Shared-first ordering: the
  // production deploy keeps instrument MP3s in deploy/shared/audio/
  // instruments/. The inthebeginning-bounce folder has no audio/samples/
  // subdirectory, so probing that path first produced a 404 for
  // piano.mp3 even though the shared path worked on the next attempt.
  const paths = baseUrl ? [baseUrl] : [
    '../../shared/audio/instruments/',
    '../shared/audio/instruments/',
    '../audio/samples/',
    '../../apps/audio/samples/',
  ];

  for (const path of paths) {
    try {
      // Test if the path is valid by trying to fetch piano.mp3
      const testResp = await fetch(path + 'piano.mp3', { method: 'HEAD' });
      if (testResp.ok) {
        await this.sampleBank.init(path, this.ctx);
        return this.sampleBank._buffers.size > 0;
      }
    } catch (e) {
      console.debug(`SynthEngine.initSamples: ${path} probe failed (${e.message})`);
    }
  }

  return false;
}

