_startEmitLoop() {
  if (this._emitInterval) clearInterval(this._emitInterval);
  this._emitInterval = setInterval(() => {
    if (!this.isPlaying || !this.onNoteEvent) return;
    const now = this.getCurrentTime();
    const speed = this._effectiveSpeed();
    const active = [];

    for (let i = Math.max(0, this._nextNote - 30); i < this._notes.length; i++) {
      const note = this._notes[i];
      const t = note.t / speed;
      const dur = (note.dur || 0.1) / speed;
      if (t > now + 0.1) break;
      if (t + dur >= now && t <= now) {
        // Normalize to the shape that background.updateFromMusic expects:
        // vel ∈ [0,1] (not raw MIDI 0-127), inst as a string so the
        // instrument-hue lookup in background.js can call .toLowerCase().
        // The old code passed raw vel and a numeric inst, which threw
        // inside _instrumentHue and killed grid color rendering.
        active.push({
          note: note.note,
          vel: Math.min(1, (note.vel || 80) / 127),
          ch: note.ch || 0,
          inst: typeof note.inst === 'string' ? note.inst : 'piano',
        });
      }
    }

    if (active.length > 0) {
      this.onNoteEvent(active);
    }
  }, 50);
}

